15	//美化输出
16	void printTask(const string tip,const string placeholder) {
17		int len = 80 - tip.length();
18		int left = len / 2;
19		int right = len - left;
20		cout << "|";
21		for (int i = 0; i < left; i++) {
22			cout << placeholder;
23		}
24		cout << tip;
25		for (int i = 0; i < right; i++) {
26			cout << placeholder;
27		}
28		cout << "|" << endl;
29	}
30	void printTips(const string tip) {
31		cout << "|********************************************************************************|" << endl;
32		printTask(tip,"*");
33		cout << "|********************************************************************************|" << endl;
34		cout << endl;
35	}
