37	//原始源程序文件：非法单词的行列定位需要回到预处理之前的源文件中查找
38	const string SOURCE_FILE = "./testCpp.txt";
39	
40	//单词类别信息
41	struct wtPair{
42		int idx;
43		int type;
44		string value;
45		wtPair(int a, int b, string c) :idx(a), type(b), value(c) {}
46	};
