124	//判断单词是否是变量名
125	bool IsIdentifier(const string word) {
126		if (word.empty()) {
127			return false;
128		}
129		//首字符只能是字母或者下划线
130		if (!isalpha((unsigned char)word[0]) && word[0] != '_') {
131			return false;
132		}
133		//其余字符只能是字母、数字或者下划线
134		for (unsigned int i = 1; i < word.length(); i++) {
135			if (!isalnum((unsigned char)word[i]) && word[i] != '_') {
136				return false;
137			}
138		}
139		return true;
140	}
141	//判断单词是否是数字
142	bool IsNum(const string word) {
143		//十进制整数：首位之后的每一个字符都必须是数字
144		for (unsigned int i = 1; i < word.length(); i++) {
145			if (!isdigit((unsigned char)word[i])) {
146				return false;
147			}
148		}
149		return true;
150	}
151	//单词-类别对照表，非法单词统一用类别码0表示
152	static map<string, int> buildWordTypeTable() {
153		map<string, int> table;
154		table["void"] = 1;
155		table["main"] = 2;
156		table["int"] = 3;
157		table["cout"] = 4;
158		table["return"] = 5;
159		table["("] = 6;
160		table[")"] = 7;
161		table["{"] = 8;
162		table["}"] = 9;
163		table["<<"] = 10;
164		table[";"] = 11;
165		table[","] = 12;
166		table["="] = 13;
167		table["*"] = 14;
168		table["/"] = 15;
169		return table;
170	}
171	//判断单词类型
172	int wtMatch(const string word) {
173		static const map<string, int> wordType = buildWordTypeTable();
174		//先查关键字与界符运算符表
175		map<string, int>::const_iterator it = wordType.find(word);
176		if (it != wordType.end()) {
177			return it->second;
178		}
179		//再判断标识符与十进制整数
180		if (IsIdentifier(word)) {
181			return 16;
182		}
183		if (IsNum(word)) {
184			return 17;
185		}
186		//都不满足则是非法单词
187		return 0;
188	}
189	//在原始源程序中逐行定位非法单词，返回“第x行第y列”形式的位置描述
190	string findError(const string fileName, const string value) {
191		ostringstream position;
192		if (value.empty()) {
193			return position.str();
194		}
195		ifstream in(fileName.c_str());
196		if (!in) {
197			return position.str();
198		}
199		string line;
200		int row = 1;
201		while (getline(in, line)) {
202			//同一行中该单词可能出现多次，逐个定位
203			string::size_type col = line.find(value);
204			while (col != string::npos) {
205				position << "第" << row << "行第" << col << "列";
206				col = line.find(value, col + 1);
207			}
208			row++;
209		}
210		in.close();
211		return position.str();
212	}
213	bool mainProcess(const string fileName, const string fileNameProcessed) {
214		printTips("开始单词扫描与分析");
215		//读入预处理之后的源程序字符流
216		ifstream in(fileName.c_str());
217		if (!in) {
218			cout << "预处理结果文件打开失败：" << fileName << endl;
219			return false;
220		}
221		string code = "", line;
222		while (getline(in, line)) {
223			code += line;
224		}
225		in.close();
226	
227		//扫描字符流进行分词，按出现顺序记录<序号,类别码,值>
228		vector<wtPair> wtSeq;
229		string word = "";
230		int idx = 0;
231		for (unsigned int i = 0; i < code.length(); i++) {
232			char c = code[i];
233			if (isalnum((unsigned char)c) || c == '_') {
234				word += c;//字母、数字、下划线归入当前单词
235				continue;
236			}
237			//遇到分隔符，先把已经累积起来的单词收尾
238			if (!word.empty()) {
239				idx++;
240				wtSeq.push_back(wtPair(idx, wtMatch(word), word));
241				word = "";
242			}
243			if (isspace((unsigned char)c)) {
244				continue;//空白只起分隔作用，本身不是单词
245			}
246			//界符与运算符自身也是一个单词，“<<”需要整体识别
247			string symbol(1, c);
248			if (c == '<' && i + 1 < code.length() && code[i + 1] == '<') {
249				symbol = "<<";
250				i++;
251			}
252			idx++;
253			wtSeq.push_back(wtPair(idx, wtMatch(symbol), symbol));
254		}
255		//字符流末尾可能还剩下一个单词
256		if (!word.empty()) {
257			idx++;
258			wtSeq.push_back(wtPair(idx, wtMatch(word), word));
259		}
260	
261		//分析结果先写入缓冲区，随后同时输出到控制台和结果文件
262		ostringstream report;
263	
264		//输出单词-类别表：合法单词留在表中显示，非法单词跳过并收集到出错序列
265		vector<wtPair> errorSeq;
266		report << setw(8) << "单词序号" << setw(12) << "单词类别" << setw(12) << "单词" << endl;
267		for (unsigned int i = 0; i < wtSeq.size(); i++) {
268			if (wtSeq[i].type <= 0) {
269				errorSeq.push_back(wtSeq[i]);
270				continue;
271			}
272			report << setw(8) << wtSeq[i].idx << setw(12) << wtSeq[i].type << setw(12) << wtSeq[i].value << endl;
273		}
274	
275		//输出出错信息：非法单词按拼写去重，同一个非法单词的所有序号与位置一并报告
276		report << "不合规单词：" << endl;
277		set<string> reported;
278		for (unsigned int i = 0; i < errorSeq.size(); i++) {
279			if (reported.count(errorSeq[i].value) > 0) {
280				continue;//该非法单词已经报告过
281			}
282			reported.insert(errorSeq[i].value);
283			report << "  " << errorSeq[i].value << ": " << endl;
284			report << "    ";
285			for (unsigned int j = i; j < errorSeq.size(); j++) {
286				if (errorSeq[j].value == errorSeq[i].value) {
287					report << "第" << errorSeq[j].idx << "个单词;";
288				}
289			}
290			report << endl;
291			report << "    位于" << findError(SOURCE_FILE, errorSeq[i].value) << endl;
292		}
293	
294		//单词表与出错信息一起显示到控制台
295		cout << report.str();
296	
297		//同样的内容保存到词法分析结果文件中
298		ofstream out(fileNameProcessed.c_str());
299		if (!out) {
300			cout << "词法分析结果文件创建失败：" << fileNameProcessed << endl;
301			return false;
302		}
303		out << report.str();
304		out.close();
305		cout << endl << "词法分析结果已保存至：" << fileNameProcessed << endl << endl;
306		printTips("单词扫描与分析已完成");
307		return true;
308	}
309	
