104	/**
105	 * Description: 函数实现以及各类操作符重载
106	 * Author: 杜登宇
107	 **/
108	
109	string load_file(string file_name) {
110		cout << "正在读取文法文件：" << file_name << endl;
111		ifstream in(file_name.c_str());
112		if (!in) {
113			cout << "文法文件打开失败，请检查文件是否存在：" << file_name << endl;
114			return "";
115		}
116		//把文件内容整体流入字符串缓冲区
117		stringstream buffer;
118		buffer << in.rdbuf();
119		in.close();
120		string text = buffer.str();
121		cout << "文法文件读取成功，文法内容如下：" << endl;
122		cout << text << endl << endl;
123		return text;
124	}
125	ostream& operator << (ostream& out, rule rule) {
126		//规则以“左部::=右部1|右部2|...”的形式输出
127		out << rule.left << "::=";
128		for (unsigned int i = 0; i < rule.right.size(); i++) {
129			if (i > 0) {
130				out << "|";
131			}
132			out << rule.right[i];
133		}
134		return out;
135	}
136	void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
137		//各条文法规则之间以空白分隔，每条规则形如“左部::=右部1|右部2|...”
138		stringstream ss(text);
139		string item;
140		while (ss >> item) {
141			string::size_type pos = item.find("::=");
142			if (pos == string::npos || pos == 0) {
143				continue;//不是一条合法的产生式，直接忽略
144			}
145			char left = item[0];
146			string rights = item.substr(pos + 3);
147	
148			//右部按“|”切分成若干个候选式
149			vector<string> parts;
150			string part = "";
151			for (unsigned int i = 0; i < rights.length(); i++) {
152				if (rights[i] == '|') {
153					parts.push_back(part);
154					part = "";
155				}
156				else {
157					part += rights[i];
158				}
159			}
160			parts.push_back(part);
161	
162			//同一个非终结符的产生式可能分开书写，合并到同一条规则中
163			int at = -1;
164			for (unsigned int i = 0; i < rules.size(); i++) {
165				if (rules[i].left == left) {
166					at = (int)i;
167					break;
168				}
169			}
170			if (at < 0) {
171				rule new_rule;
172				new_rule.left = left;
173				rules.push_back(new_rule);
174				at = (int)rules.size() - 1;
175			}
176			for (unsigned int i = 0; i < parts.size(); i++) {
177				if (!parts[i].empty()) {
178					rules[at].right.push_back(parts[i]);
179				}
180			}
181			//出现在规则左部的一定是非终结符
182			non_terminal.insert(left);
183		}
184	
185		//所有规则左部都收集完毕之后，再回头区分右部中的终结符和非终结符
186		for (unsigned int i = 0; i < rules.size(); i++) {
187			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
188				const string& part = rules[i].right[j];
189				right_parts.insert(part);
190				for (unsigned int k = 0; k < part.length(); k++) {
191					char c = part[k];
192					if (c == '@') {
193						continue;//“@”代表空串ε，既不是终结符也不是非终结符
194					}
195					if (non_terminal.count(c) > 0) {
196						continue;
197					}
198					if (isupper((unsigned char)c)) {
199						non_terminal.insert(c);//大写字母一律看作非终结符
200					}
201					else {
202						terminal.insert(c);
203					}
204				}
205			}
206		}
207	}
208	void check_rules(const vector<rule> rules) {
209		//按提取顺序逐条输出文法规则
210		cout << "提取文法规则：" << endl;
211		if (rules.empty()) {
212			//文法文件为空或者书写格式有误时给出提示，避免只打印一个空行
213			cout << "    （未提取到任何文法规则，请检查文法文件的书写格式）" << endl << endl;
214			return;
215		}
216		for (unsigned int i = 0; i < rules.size(); i++) {
217			cout << "    " << rules[i] << endl;
218		}
219		cout << endl;
220	}
221	template <class T>
222	void check_set(set<T> set_, string tip) {
223		//按集合内部的有序性依次输出各个元素
224		cout << tip << "：" << endl;
225		cout << "    ";
226		if (set_.empty()) {
227			//空集合同样给出提示，方便对照检查提取结果
228			cout << "（空）" << endl << endl;
229			return;
230		}
231		for (typename set<T>::iterator it = set_.begin(); it != set_.end(); it++) {
232			if (it != set_.begin()) {
233				cout << "  ";
234			}
235			cout << *it;
236		}
237		cout << endl << endl;
