239	ostream& operator << (ostream& out, F_set f_set) {
240		//根据判别符区分两类集合，形如“First(右部)={a,b}”或者“Follow(非终结符)={#,a}”
241		if (f_set.is_first) {
242			out << "First(" << f_set.left << ")={";
243		}
244		else {
245			out << "Follow(" << f_set.left << ")={";
246		}
247		//集合元素之间用逗号分隔
248		for (set<char>::iterator it = f_set.right.begin(); it != f_set.right.end(); it++) {
249			if (it != f_set.right.begin()) {
250				out << ",";
251			}
252			out << *it;
253		}
254		out << "}";
255		return out;
