import sys, itertools

def parse_grammar(text):
    rules = {}   # nt -> list of list of symbols
    order = []
    for item in text.split():
        p = item.find("::=")
        if p <= 0: continue
        left = item[0]
        rights = item[p+3:]
        for alt in rights.split("|"):
            if alt == "": continue
            rules.setdefault(left, [])
            if left not in order: order.append(left)
            rules[left].append([] if alt == "@" else list(alt))
    return rules, order

def earley(rules, start, s):
    n = len(s)
    chart = [set() for _ in range(n+1)]
    def add(i, item):
        if item not in chart[i]:
            chart[i].add(item)
            return True
        return False
    for prod in rules[start]:
        add(0, (start, tuple(prod), 0, 0))
    for i in range(n+1):
        changed = True
        while changed:
            changed = False
            for item in list(chart[i]):
                (lhs, prod, dot, origin) = item
                if dot < len(prod):
                    sym = prod[dot]
                    if sym in rules:   # predict
                        for p in rules[sym]:
                            if add(i, (sym, tuple(p), 0, i)): changed = True
                    else:              # scan
                        if i < n and s[i] == sym:
                            chart[i+1].add((lhs, prod, dot+1, origin))
                else:                  # complete
                    for it2 in list(chart[origin]):
                        (l2, p2, d2, o2) = it2
                        if d2 < len(p2) and p2[d2] == lhs:
                            if add(i, (l2, p2, d2+1, o2)): changed = True
    for item in chart[n]:
        (lhs, prod, dot, origin) = item
        if lhs == start and dot == len(prod) and origin == 0:
            return True
    return False

if __name__ == "__main__":
    text = open(sys.argv[1]).read()
    rules, order = parse_grammar(text)
    start = order[0]
    maxlen = int(sys.argv[2])
    alpha = sorted({c for prods in rules.values() for p in prods for c in p if c not in rules})
    sys.stderr.write("start=%s alpha=%s\n" % (start, "".join(alpha)))
    for L in range(0, maxlen+1):
        for tup in itertools.product(alpha, repeat=L):
            s = "".join(tup)
            print("%s\t%d" % (s, 1 if earley(rules, start, list(s)) else 0))

