import random, subprocess, sys, itertools

HARNESS = "/tmp/ff/harness"

def parse_rules(text):
    rules = []          # list of (left, [alts])
    order = []
    d = {}
    for item in text.split():
        p = item.find("::=")
        if p <= 0: continue
        left = item[0]
        alts = [a for a in item[p+3:].split("|") if a != ""]
        if left not in d:
            d[left] = []
            order.append(left)
        d[left].extend(alts)
    return order, d

def reference(text):
    order, d = parse_rules(text)
    NTs = set(order)                      # non-terminal == appears as a rule left
    # FIRST of a symbol string, fixpoint style
    firstNT = {A: set() for A in order}   # may contain '@'
    def first_str(ss):
        res = set()
        all_eps = True
        for ch in ss:
            if ch == '@':
                continue
            if ch not in NTs:
                res.add(ch); all_eps = False; break
            res |= (firstNT[ch] - {'@'})
            if '@' not in firstNT[ch]:
                all_eps = False; break
        if all_eps:
            res.add('@')
        return res
    changed = True
    while changed:
        changed = False
        for A in order:
            for alt in d[A]:
                f = first_str(alt)
                if not f <= firstNT[A]:
                    firstNT[A] |= f; changed = True
    # FOLLOW, seeded with '#' for every non-terminal (project convention)
    follow = {A: set('#') for A in order}
    changed = True
    while changed:
        changed = False
        for A in order:
            for alt in d[A]:
                for i, ch in enumerate(alt):
                    if ch not in NTs: continue
                    rest = alt[i+1:]
                    f = first_str(rest) if rest else set('@')
                    add = f - {'@'}
                    if '@' in f:
                        add |= follow[A]
                    if not add <= follow[ch]:
                        follow[ch] |= add; changed = True
    return order, d, NTs, first_str, follow

def run(text):
    out = subprocess.run([HARNESS, text], capture_output=True, text=True)
    if out.returncode != 0:
        return None, out.stdout + out.stderr
    got = {}
    for line in out.stdout.splitlines():
        parts = line.split(" ")
        if parts[0] == "FIRST":
            got[("F", parts[1])] = set(parts[2]) if len(parts) > 2 else set()
        elif parts[0] == "FOLLOW":
            got[("L", parts[1])] = set(parts[2]) if len(parts) > 2 else set()
    return got, out.stdout

def gen(rng):
    nnt = rng.randint(1, 4)
    nts = "EABCD"[:nnt+1][:nnt] if nnt <= 4 else "EABCD"
    nts = list("SABC")[:nnt]
    terms = list("abc")[:rng.randint(1, 3)]
    items = []
    for A in nts:
        nalt = rng.randint(1, 3)
        alts = []
        for _ in range(nalt):
            L = rng.randint(0, 3)
            if L == 0:
                alts.append("@")
            else:
                alts.append("".join(rng.choice(nts + terms) for _ in range(L)))
        items.append("%s::=%s" % (A, "|".join(alts)))
    return "  ".join(items)

def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
    N = int(sys.argv[2]) if len(sys.argv) > 2 else 500
    bad = 0
    for n in range(N):
        text = gen(rng)
        order, d, NTs, first_str, follow = reference(text)
        if not order: continue
        got, raw = run(text)
        if got is None:
            print("CRASH on grammar: %s\n%s" % (text, raw)); bad += 1; continue
        for key, val in sorted(got.items()):
            kind, name = key
            if kind == "F":
                want = first_str(name)
            else:
                want = follow[name]
            if val != want:
                print("MISMATCH %s grammar=%r  sym=%r  cpp=%s  ref=%s" %
                      ("FIRST" if kind == "F" else "FOLLOW", text, name,
                       "".join(sorted(val)), "".join(sorted(want))))
                bad += 1
    print("%d grammars, %d discrepancies" % (N, bad))

main()

