124	//判断单词是否是变量名
125	bool IsIdentifier(const string word) {
126		if (word.empty()) {
127			return false;
128		}
129		//首字符只能是字母或者下划线
130		if (!isalpha((unsigned char)word[0]) && word[0] != '_') {
131			return false;
132		}
133		//其余字符只能是字母、数字或者下划线
134		for (unsigned int i = 1; i < word.length(); i++) {
135			if (!isalnum((unsigned char)word[i]) && word[i] != '_') {
136				return false;
137			}
138		}
139		return true;
140	}
141	//判断单词是否是数字
142	bool IsNum(const string word) {
143		//十进制整数的判定规则：首位之后的每一个字符都必须是数字。
144		//首位本身不参与判断，wtMatch会先用IsIdentifier把字母、下划线打头的单词挑走，
145		//所以真正落到这里的只有数字打头的单词，例如“201”合法而“2res”不合法。
146		for (unsigned int i = 1; i < word.length(); i++) {
147			if (!isdigit((unsigned char)word[i])) {
148				return false;
149			}
150		}
151		return true;
152	}
153	//单词-类别对照表，非法单词统一用类别码0表示
154	static map<string, int> buildWordTypeTable() {
155		map<string, int> table;
156		table["void"] = 1;
157		table["main"] = 2;
158		table["int"] = 3;
159		table["cout"] = 4;
160		table["return"] = 5;
161		table["("] = 6;
162		table[")"] = 7;
163		table["{"] = 8;
164		table["}"] = 9;
165		table["<<"] = 10;
166		table[";"] = 11;
167		table[","] = 12;
168		table["="] = 13;
169		table["*"] = 14;
170		table["/"] = 15;
171		return table;
172	}
173	//判断单词类型
174	int wtMatch(const string word) {
175		static const map<string, int> wordType = buildWordTypeTable();
176		//先查关键字与界符运算符表
177		map<string, int>::const_iterator it = wordType.find(word);
178		if (it != wordType.end()) {
179			return it->second;
180		}
181		//再判断标识符与十进制整数
182		if (IsIdentifier(word)) {
183			return 16;
184		}
185		if (IsNum(word)) {
186			return 17;
187		}
188		//都不满足则是非法单词
189		return 0;
190	}
191	//在原始源程序中逐行定位非法单词，返回“第x行第y列”形式的位置描述
192	string findError(const string fileName, const string value) {
193		ostringstream position;
194		if (value.empty()) {
195			return position.str();
196		}
197		ifstream in(fileName.c_str());
198		if (!in) {
199			return position.str();
200		}
201		string line;
202		int row = 1;
203		while (getline(in, line)) {
204			//同一行中该单词可能出现多次，逐个定位
205			string::size_type col = line.find(value);
206			while (col != string::npos) {
207				position << "第" << row << "行第" << col << "列";
208				col = line.find(value, col + 1);
209			}
210			row++;
211		}
212		in.close();
213		return position.str();
214	}
215	bool mainProcess(const string fileName, const string fileNameProcessed) {
216		printTips("开始单词扫描与分析");
217		//读入预处理之后的源程序字符流
218		ifstream in(fileName.c_str());
219		if (!in) {
220			cout << "预处理结果文件打开失败：" << fileName << endl;
221			return false;
222		}
223		string code = "", line;
224		while (getline(in, line)) {
225			code += line;
226		}
227		in.close();
228	
229		//扫描字符流进行分词，按出现顺序记录<序号,类别码,值>
230		vector<wtPair> wtSeq;
231		string word = "";
232		int idx = 0;
233		for (unsigned int i = 0; i < code.length(); i++) {
234			char c = code[i];
235			if (isalnum((unsigned char)c) || c == '_') {
236				word += c;//字母、数字、下划线归入当前单词
237				continue;
238			}
239			//遇到分隔符，先把已经累积起来的单词收尾
240			if (!word.empty()) {
241				idx++;
242				wtSeq.push_back(wtPair(idx, wtMatch(word), word));
243				word = "";
244			}
245			if (isspace((unsigned char)c)) {
246				continue;//空白只起分隔作用，本身不是单词
247			}
248			//界符与运算符自身也是一个单词，“<<”需要整体识别
249			string symbol(1, c);
250			if (c == '<' && i + 1 < code.length() && code[i + 1] == '<') {
251				symbol = "<<";
252				i++;
253			}
254			idx++;
255			wtSeq.push_back(wtPair(idx, wtMatch(symbol), symbol));
256		}
257		//字符流末尾可能还剩下一个单词
258		if (!word.empty()) {
259			idx++;
260			wtSeq.push_back(wtPair(idx, wtMatch(word), word));
261		}
262	
263		//分析结果先写入缓冲区，随后同时输出到控制台和结果文件
264		ostringstream report;
265	
266		//输出单词-类别表：合法单词留在表中显示，非法单词跳过并收集到出错序列
267		vector<wtPair> errorSeq;
268		report << setw(8) << "单词序号" << setw(12) << "单词类别" << setw(12) << "单词" << endl;
269		for (unsigned int i = 0; i < wtSeq.size(); i++) {
270			if (wtSeq[i].type <= 0) {
271				errorSeq.push_back(wtSeq[i]);
272				continue;
273			}
274			report << setw(8) << wtSeq[i].idx << setw(12) << wtSeq[i].type << setw(12) << wtSeq[i].value << endl;
275		}
276	
277		//输出出错信息：非法单词按拼写去重，同一个非法单词的所有序号与位置一并报告
278		report << "不合规单词：" << endl;
279		set<string> reported;
280		for (unsigned int i = 0; i < errorSeq.size(); i++) {
281			if (reported.count(errorSeq[i].value) > 0) {
282				continue;//该非法单词已经报告过
283			}
284			reported.insert(errorSeq[i].value);
285			report << "  " << errorSeq[i].value << ": " << endl;
286			report << "    ";
287			for (unsigned int j = i; j < errorSeq.size(); j++) {
288				if (errorSeq[j].value == errorSeq[i].value) {
289					report << "第" << errorSeq[j].idx << "个单词;";
290				}
291			}
292			report << endl;
293			report << "    位于" << findError(SOURCE_FILE, errorSeq[i].value) << endl;
294		}
295	
296		//单词表与出错信息一起显示到控制台
297		cout << report.str();
298	
299		//同样的内容保存到词法分析结果文件中
300		ofstream out(fileNameProcessed.c_str());
301		if (!out) {
302			cout << "词法分析结果文件创建失败：" << fileNameProcessed << endl;
303			return false;
304		}
305		out << report.str();
306		out.close();
307		cout << endl << "词法分析结果已保存至：" << fileNameProcessed << endl << endl;
308		printTips("单词扫描与分析已完成");
309		return true;
310	}
