136	void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
137		//每条规则形如“左部::=右部1|右部2|...”，规则之间以空白分隔；
138		//“::=”两侧以及候选式内部允许夹杂空白与换行，提取时一律忽略
139		vector<string::size_type> marks;//文本中所有“::=”出现的位置
140		for (string::size_type pos = text.find("::="); pos != string::npos; pos = text.find("::=", pos + 3)) {
141			marks.push_back(pos);
142		}
143		for (unsigned int m = 0; m < marks.size(); m++) {
144			//“::=”之前最近的一个非空白字符就是本条规则的左部
145			string::size_type left_at = string::npos;
146			for (string::size_type k = marks[m]; k > 0; k--) {
147				if (!isspace((unsigned char)text[k - 1])) {
148					left_at = k - 1;
149					break;
150				}
151			}
152			if (left_at == string::npos) {
153				continue;//找不到左部，不是一条合法的产生式，直接忽略
154			}
155			char left = text[left_at];
156			//右部一直延伸到下一条规则的左部之前，最后一条规则则延伸到文本末尾
157			string::size_type end = text.length();
158			if (m + 1 < marks.size()) {
159				end = marks[m + 1];
160				while (end > marks[m] + 3 && isspace((unsigned char)text[end - 1])) {
161					end--;
162				}
163				if (end > marks[m] + 3) {
164					end--;//下一条规则的左部字符不属于本条规则的右部
165				}
166			}
167			string rights = text.substr(marks[m] + 3, end - marks[m] - 3);
168	
169			//右部按“|”切分成若干个候选式，其中的空白只起分隔作用
170			vector<string> parts;
171			string part = "";
172			for (unsigned int i = 0; i < rights.length(); i++) {
173				if (isspace((unsigned char)rights[i])) {
174					continue;
175				}
176				if (rights[i] == '|') {
177					parts.push_back(part);
178					part = "";
179				}
180				else {
181					part += rights[i];
182				}
183			}
184			parts.push_back(part);
185	
186			//同一个非终结符的产生式可能分开书写，合并到同一条规则中
187			int at = -1;
188			for (unsigned int i = 0; i < rules.size(); i++) {
189				if (rules[i].left == left) {
190					at = (int)i;
191					break;
192				}
193			}
194			if (at < 0) {
195				rule new_rule;
196				new_rule.left = left;
197				rules.push_back(new_rule);
198				at = (int)rules.size() - 1;
199			}
200			for (unsigned int i = 0; i < parts.size(); i++) {
201				if (!parts[i].empty()) {
202					rules[at].right.push_back(parts[i]);
203				}
204			}
205			//出现在规则左部的一定是非终结符
206			non_terminal.insert(left);
207		}
208	
209		//所有规则左部都收集完毕之后，再回头区分右部中的终结符和非终结符
210		for (unsigned int i = 0; i < rules.size(); i++) {
211			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
212				const string& part = rules[i].right[j];
213				right_parts.insert(part);
214				for (unsigned int k = 0; k < part.length(); k++) {
215					char c = part[k];
216					if (c == '@') {
217						continue;//“@”代表空串ε，既不是终结符也不是非终结符
218					}
219					if (non_terminal.count(c) > 0) {
220						continue;
221					}
222					if (isupper((unsigned char)c)) {
223						non_terminal.insert(c);//大写字母一律看作非终结符
224					}
225					else {
226						terminal.insert(c);
227					}
228				}
229			}
230		}
231	}
