263	ostream& operator << (ostream& out, F_set f_set) {
264		//根据判别符区分两类集合，形如“First(右部)={a,b}”或者“Follow(非终结符)={#,a}”
265		if (f_set.is_first) {
266			out << "First(" << f_set.left << ")={";
267		}
268		else {
269			out << "Follow(" << f_set.left << ")={";
270		}
271		//集合元素之间用逗号分隔
272		for (set<char>::iterator it = f_set.right.begin(); it != f_set.right.end(); it++) {
273			if (it != f_set.right.begin()) {
274				out << ",";
275			}
276			out << *it;
277		}
278		out << "}";
