281	//判断一个字符是否是非终结符：作为规则左部出现过的字符，以及大写字母，都算非终结符
282	//（与提取阶段的判定保持一致，只出现在右部却没有产生式的大写字母同样按非终结符处理）
283	static bool is_non_terminal(const char c, const vector<rule>& rules) {
284		if (isupper((unsigned char)c)) {
285			return true;
286		}
287		for (unsigned int i = 0; i < rules.size(); i++) {
288			if (rules[i].left == c) {
289				return true;
290			}
291		}
292		return false;
293	}
294	//求符号串ss的First集，visiting记录当前正在展开的非终结符，防止左递归文法导致无限递归
295	static set<char> firstOf(const string ss, const vector<rule>& rules, set<char>& visiting) {
296		set<char> result;
297		bool all_epsilon = true;//ss中的每个符号都能推出空串时，First集里才有“@”
298		for (unsigned int i = 0; i < ss.length(); i++) {
299			char c = ss[i];
300			if (c == '@') {
301				continue;//“@”本身就代表空串，不影响它后面的符号
302			}
303			if (!is_non_terminal(c, rules)) {
304				result.insert(c);//终结符直接进入First集
305				all_epsilon = false;
306				break;//终结符后面的符号对First集不再有贡献
307			}
308			if (visiting.count(c) > 0) {
309				all_epsilon = false;
310				break;//该非终结符正处在展开过程中，再展开下去就会陷入死循环
311			}
312			//非终结符：把它的每一个候选式的First集并进来
313			visiting.insert(c);
314			bool has_epsilon = false;
315			for (unsigned int j = 0; j < rules.size(); j++) {
316				if (rules[j].left != c) {
317					continue;
318				}
319				for (unsigned int k = 0; k < rules[j].right.size(); k++) {
320					set<char> sub = firstOf(rules[j].right[k], rules, visiting);
321					for (set<char>::iterator it = sub.begin(); it != sub.end(); it++) {
322						if (*it == '@') {
323							has_epsilon = true;//该候选式能推出空串，暂不收录“@”
324						}
325						else {
326							result.insert(*it);
327						}
328					}
329				}
330			}
331			visiting.erase(c);
332			if (!has_epsilon) {
333				all_epsilon = false;
334				break;//该非终结符推不出空串，后面的符号对First集不再有贡献
335			}
336		}
337		if (all_epsilon) {
338			result.insert('@');//整个符号串都能推出空串
339		}
340		return result;
341	}
342	F_set findFirst(const string ss, vector<rule> rules) {
343		F_set f_set;
344		f_set.is_first = true;
345		f_set.left = ss;
346		set<char> visiting;
347		f_set.right = firstOf(ss, rules, visiting);
348		return f_set;
349	}
350	vector<F_set> checkFirst(set<string> right_parts, vector<rule> rules) {
351		//逐个求出各条规则右部符号串的First集，重复的右部在set里已经合并，只会显示一次
352		vector<F_set> f_sets;
353		cout << "各规则右部的First集：" << endl;
354		for (set<string>::iterator it = right_parts.begin(); it != right_parts.end(); it++) {
355			F_set f_set = findFirst(*it, rules);
356			cout << "    " << f_set << endl;
357			f_sets.push_back(f_set);
358		}
359		cout << endl;
360		return f_sets;
361	}
362	//求非终结符的Follow集，visiting记录当前正在求Follow集的非终结符，防止规则相互引用导致无限递归
363	static set<char> followOf(const char non_terminal, const vector<rule>& rules, set<char>& visiting) {
364		set<char> result;
365		result.insert('#');//“#”是输入串的结束标志，任何非终结符的Follow集里都带上它
366		visiting.insert(non_terminal);
367		for (unsigned int i = 0; i < rules.size(); i++) {
368			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
369				const string& part = rules[i].right[j];
370				//同一个候选式中该非终结符可能出现多次，逐个位置考察
371				string::size_type pos = part.find(non_terminal);
372				while (pos != string::npos) {
373					bool at_end = true;//其后的符号串是否能推出空串（出现在末尾时同样成立）
374					if (pos + 1 < part.length()) {
375						//紧跟其后的符号串的First集去掉“@”之后并入Follow集
376						set<char> visiting_first;
377						set<char> first = firstOf(part.substr(pos + 1), rules, visiting_first);
378						at_end = false;
379						for (set<char>::iterator it = first.begin(); it != first.end(); it++) {
380							if (*it == '@') {
381								at_end = true;//后继符号串能推出空串，还要并入规则左部的Follow集
382							}
383							else {
384								result.insert(*it);
385							}
386						}
387					}
388					if (at_end && visiting.count(rules[i].left) == 0) {
389						//位于规则末尾时，规则左部的Follow集整个并入
390						set<char> parent = followOf(rules[i].left, rules, visiting);
391						result.insert(parent.begin(), parent.end());
392					}
393					pos = part.find(non_terminal, pos + 1);
394				}
395			}
396		}
397		visiting.erase(non_terminal);
398		return result;
399	}
400	F_set findFollow(const char non_terminal, vector<rule> rules) {
401		F_set f_set;
402		f_set.is_first = false;
403		f_set.left = non_terminal;
404		set<char> visiting;
405		f_set.right = followOf(non_terminal, rules, visiting);
406		return f_set;
407	}
408	vector<F_set> checkFollow(set<char> non_terminal, vector<rule> rules) {
409		//逐个求出各个非终结符的Follow集

410		vector<F_set> f_sets;
411		cout << "各非终结符的Follow集：" << endl;
412		for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
413			F_set f_set = findFollow(*it, rules);
414			cout << "    " << f_set << endl;
415			f_sets.push_back(f_set);
416		}
417		cout << endl;
418		return f_sets;
419	}
420	LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules) {
421		LL_1_table table;
422		//行表头：按规则书写的先后顺序排列非终结符，这样第一行对应的就是文法的开始符号
423		for (unsigned int i = 0; i < rules.size(); i++) {
424			if (find(table.row.begin(), table.row.end(), rules[i].left) == table.row.end()) {
425				table.row.push_back(rules[i].left);
426			}
427		}
428		//只出现在右部、没有产生式的非终结符同样占一行，避免分析表缺行
429		for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
430			if (find(table.row.begin(), table.row.end(), *it) == table.row.end()) {
431				table.row.push_back(*it);
432			}
433		}
434		//列表头：全部终结符再加上输入串的结束标志“#”，“#”固定放在最后一列
435		terminal.insert('#');
436		for (set<char>::iterator it = terminal.begin(); it != terminal.end(); it++) {
437			if (*it != '#' && *it != '@') {
438				table.col.push_back(*it);
439			}
440		}
441		table.col.push_back('#');
442		//表中每个单元格先放一条空规则，能填入产生式的单元格随后再覆盖
443		rule blank;
444		blank.left = 0;
445		table.rules.assign(table.row.size() * table.col.size(), blank);
446	
447		//逐条候选式填表：候选式的First集里有哪个终结符，就把它填到对应的单元格里
448		for (unsigned int i = 0; i < rules.size(); i++) {
449			//行号由规则左部决定
450			vector<char>::iterator row_it = find(table.row.begin(), table.row.end(), rules[i].left);
451			if (row_it == table.row.end()) {
452				continue;
453			}
454			unsigned int r = (unsigned int)(row_it - table.row.begin());
455			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
456				//单元格里存放的是“左部::=某一个候选式”这样一条单候选式规则
457				rule cell;
458				cell.left = rules[i].left;
459				cell.right.push_back(rules[i].right[j]);
460	
461				F_set first = findFirst(rules[i].right[j], rules);
462				set<char> heads = first.right;
463				//候选式能推出空串时，改用左部的Follow集来决定填表的位置
464				if (heads.count('@') > 0) {
465					F_set follow = findFollow(rules[i].left, rules);
466					heads.insert(follow.right.begin(), follow.right.end());
467				}
468				for (set<char>::iterator it = heads.begin(); it != heads.end(); it++) {
469					if (*it == '@') {
470						continue;//“@”自身不是终结符，不占分析表的列
471					}
472					vector<char>::iterator col_it = find(table.col.begin(), table.col.end(), *it);
473					if (col_it == table.col.end()) {
474						continue;
475					}
476					unsigned int c = (unsigned int)(col_it - table.col.begin());
477					table.rules[r * table.col.size() + c] = cell;
478				}
479			}
480		}
481		return table;
482	}
483	ostream& operator << (ostream& out, LL_1_table table) {
484		out << "LL(1)分析表如下：" << endl;
485		//列表头：第一列留给非终结符，其余各列依次对应一个终结符
486		out << setw(8) << " ";
487		for (unsigned int j = 0; j < table.col.size(); j++) {
488			out << setw(12) << table.col[j];
489		}
490		out << endl;
491		//逐行输出：行首是非终结符，其后是各个单元格里的产生式，空单元格留白
492		for (unsigned int i = 0; i < table.row.size(); i++) {
493			out << setw(8) << table.row[i];
494			for (unsigned int j = 0; j < table.col.size(); j++) {
495				ostringstream cell;
496				unsigned int at = i * table.col.size() + j;
497				if (at < table.rules.size() && !table.rules[at].right.empty()) {
498					cell << table.rules[at];
499				}
500				out << setw(12) << cell.str();
501			}
502			out << endl;
503		}
504		out << endl;
505		return out;
506	}
507	void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
508		//分析栈按“栈底到栈顶”的顺序输出，栈底的“#”排在最左边
509		string analysis = "";
510		while (!analysis_s.empty()) {
511			analysis = string(1, analysis_s.top()) + analysis;
512			analysis_s.pop();
513		}
514		//输入栈按“栈顶到栈底”的顺序输出，正好是剩余的输入串
515		string input = "";
516		while (!input_s.empty()) {
517			input += input_s.top();
518			input_s.pop();
519		}
520		//所用产生式：右部为空说明这一步不是推导而是终结符匹配
521		ostringstream action;
522		if (!rule_temp.right.empty()) {
523			action << rule_temp;
524		}
525		else if (rule_temp.left != 0) {
526			action << "“" << rule_temp.left << "”匹配";
527		}
528		cout << setw(20) << analysis << setw(20) << input << setw(20) << action.str() << endl;
529	}
530	void syntacticAnalysis(LL_1_table table) {
531		cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
532		string input;
533		cin >> input;
534		//结束标志“#”由程序自己压栈，用户按习惯在串尾多写一个“#”时把它去掉，
535		//输出分析结论时仍然显示用户输入的原串
536		string sentence = input;
537		if (!sentence.empty() && sentence[sentence.length() - 1] == '#') {
538			sentence = sentence.substr(0, sentence.length() - 1);
539		}
540	
541		//分析栈：栈底压入结束标志“#”，其上压入文法的开始符号，即分析表的第一行
542		stack<char> analysis_s;
543		analysis_s.push('#');
544		if (!table.row.empty()) {
545			analysis_s.push(table.row[0]);
546		}
547		//输入栈：结束标志“#”压在栈底，待分析的字符串倒序入栈，栈顶就是当前输入符号
548		stack<char> input_s;
549		input_s.push('#');
550		for (int i = (int)sentence.length() - 1; i >= 0; i--) {
551			input_s.push(sentence[i]);
552		}
553	
554		//分析是否成功的标志，一旦出现无法匹配或者查不到产生式的情况就置为false
555		bool success = true;
556		if (table.row.empty()) {
557			cout << "没有可用的文法规则，无法进行语法分析" << endl;
558			success = false;
559		}
560		if (sentence.find('#') != string::npos) {
561			//“#”是输入串的结束标志，只能出现在待分析字符串的末尾
562			cout << "待分析的字符串中间不能出现结束标志“#”" << endl;
563			success = false;
564		}
565	
566		//分析过程表头
567		cout << endl << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(20) << "所用产生式" << endl;
568	
569		//表驱动的分析过程：栈顶是非终结符就查表展开，是终结符就与当前输入符号匹配
570		rule rule_temp;//本步骤所用的产生式，右部为空表示该步骤只是一次终结符匹配
571		rule_temp.left = 0;
572		unsigned long step = 0;
573		//推导步数的上限随输入串长度增长，正常的分析过程远远达不到这个数量级
574		const unsigned long max_step = 100000UL + 1000UL * (unsigned long)sentence.length();
575		while (success) {
576			if (analysis_s.empty() || input_s.empty()) {
577				cout << "分析栈或者输入串提前变空，分析终止" << endl;
578				success = false;
579				break;
580			}
581			char top = analysis_s.top();
582			char cur = input_s.top();
583			if (top == '#' && cur == '#') {
584				//分析栈与输入串同时到达结束标志，分析成功结束
585				rule_temp.left = 0;
586				rule_temp.right.clear();
587				print_state(analysis_s, input_s, rule_temp);
588				break;
589			}
590			if (++step > max_step) {
591				cout << "推导步骤过多，文法可能存在左递归，分析终止" << endl;
592				success = false;
593				break;
594			}
595			vector<char>::iterator row_it = find(table.row.begin(), table.row.end(), top);
596			if (row_it == table.row.end()) {
597				//栈顶是终结符：与当前输入符号相同才能一起弹出，否则分析失败
598				if (top != cur) {
599					cout << "栈顶终结符" << top << "与当前输入符号" << cur << "不匹配，分析终止" << endl;
600					success = false;
601					break;
602				}
603				rule_temp.left = top;
604				rule_temp.right.clear();
605				print_state(analysis_s, input_s, rule_temp);
606				analysis_s.pop();
607				input_s.pop();
608				continue;
609			}
610			//栈顶是非终结符：用当前输入符号查分析表，取出对应的产生式
611			vector<char>::iterator col_it = find(table.col.begin(), table.col.end(), cur);
612			unsigned int at = 0;
613			if (col_it != table.col.end()) {
614				at = (unsigned int)(row_it - table.row.begin()) * table.col.size() + (unsigned int)(col_it - table.col.begin());
615			}
616			if (col_it == table.col.end() || at >= table.rules.size() || table.rules[at].right.empty()) {
617				cout << "分析表中(" << top << "," << cur << ")处为空，分析终止" << endl;
618				success = false;
619				break;
620			}
621			rule_temp = table.rules[at];
622			print_state(analysis_s, input_s, rule_temp);
623			//用产生式右部替换栈顶的非终结符，右部倒序入栈保证最左边的符号处在栈顶
624			analysis_s.pop();
625			string right = rule_temp.right[0];
626			for (int i = (int)right.length() - 1; i >= 0; i--) {
627				if (right[i] != '@') {
628					analysis_s.push(right[i]);//“@”代表空串，不入栈
629				}
630			}
631		}
632	
633		cout << endl << "字符串" << input;
634		if (!success) {
635			cout << "不";
636		}
637		cout << "是该文法的句子" << endl;
638	}
